<?php require 'config.php';require 'includes/functions.php';require_login();verify_csrf();$cart=$_SESSION['cart']??[];if(!$cart)go('cart.php');$ids=array_map('intval',array_keys($cart));$in=implode(',',array_fill(0,count($ids),'?'));$s=$pdo->prepare("SELECT * FROM products WHERE active=1 AND id IN ($in)");$s->execute($ids);$items=$s->fetchAll();$total=0;foreach($items as $p)$total+=$p['price']*$cart[$p['id']];if($_SERVER['REQUEST_METHOD']==='POST'){$address=trim($_POST['address']??'');if(!$address)flash('Delivery address is required.','error');else{try{$pdo->beginTransaction();foreach($items as $p){if($p['stock']<$cart[$p['id']])throw new Exception('Insufficient stock for '.$p['name']);}$s=$pdo->prepare("INSERT INTO orders(user_id,total_amount,shipping_address,status,payment_status) VALUES(?,?,?,'placed','pending')");$s->execute([current_user()['id'],$total,$address]);$oid=(int)$pdo->lastInsertId();$ins=$pdo->prepare("INSERT INTO order_items(order_id,product_id,quantity,unit_price) VALUES(?,?,?,?)");$upd=$pdo->prepare("UPDATE products SET stock=stock-? WHERE id=? AND stock>=?");foreach($items as $p){$qty=$cart[$p['id']];$ins->execute([$oid,$p['id'],$qty,$p['price']]);$upd->execute([$qty,$p['id'],$qty]);if(!$upd->rowCount())throw new Exception('Stock changed during checkout.');}$pdo->commit();unset($_SESSION['cart']);flash('Order placed successfully. This demo does not collect payment.');go('account.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('Checkout failed: '.$e->getMessage(),'error');}}}$title='Checkout';require 'includes/header.php';?><div class="formbox wide"><span class="eyebrow">ALMOST YOURS</span><h1>Checkout</h1><p>Order total: <b><?=money($total)?></b></p><form method="post"><?=csrf_field()?><label>Delivery address<textarea name="address" rows="4" required></textarea></label><p class="muted">Demo checkout places an order without charging a payment method.</p><button class="button dark full">Place order</button></form></div><?php require 'includes/footer.php';?>